"use strict";(globalThis.webpackChunknemerald_web=globalThis.webpackChunknemerald_web||[]).push([[2189],{7107(e){e.exports=JSON.parse('{"tag":{"label":"settings","permalink":"/docs/tags/settings","allTagsPath":"/docs/tags","count":10,"items":[{"id":"apps/ringotel/android-app/general/android-app-settings--r6rizuxce9ze29hbwv9o8yr9","title":"App Settings","description":"In the App Settings, you can set Call Forwarding, Voicemail, and other features according to your needs.","permalink":"/docs/apps/android-app-settings--r6rizuxce9ze29hbwv9o8yr9"},{"id":"apps/ringotel/ios-app/general/ios-app-settings--k6r55vy13tjohxf7yx86uo1h","title":"App Settings","description":"In the App Settings, you can set Call Forwarding, Voicemail, and some other features according to your needs.","permalink":"/docs/apps/ios-app-settings--k6r55vy13tjohxf7yx86uo1h"},{"id":"apps/ringotel/desktop-app/general/desktop-audio-settings--a9uwhby2gvts8tp969uze2yw","title":"Audio settings","description":"1. Jitter buffer length control (helps to improve call quality in case of unstable internet connections).","permalink":"/docs/apps/desktop-audio-settings--a9uwhby2gvts8tp969uze2yw"},{"id":"apps/ringotel/android-app/general/android-call-settings--nnzhvklnaayrh61sd4o54ewl","title":"Call Settings","description":"Looking for an&#x20;PC/Mac or&#x20;iOS version of this article?","permalink":"/docs/apps/android-call-settings--nnzhvklnaayrh61sd4o54ewl"},{"id":"apps/ringotel/desktop-app/general/desktop-call-settings--w8x57mdttk6m2ucvcxpao23m","title":"Call Settings","description":"Looking for an&#x20;Android or&#x20;iOS version of this article?","permalink":"/docs/apps/desktop-call-settings--w8x57mdttk6m2ucvcxpao23m"},{"id":"apps/ringotel/ios-app/general/ios-call-settings--e17r8k0ifbuhd4pwldlm7xhc","title":"Call Settings","description":"Looking for an&#x20;PC/Mac or&#x20;Android version of this article?","permalink":"/docs/apps/ios-call-settings--e17r8k0ifbuhd4pwldlm7xhc"},{"id":"apps/ringotel/desktop-app/general/desktop-general-app-settings--g4g5p30bgtm5ofmc1sxsa040","title":"General App Settings","description":"You can configure a pop-up window during incoming calls and voicemails, trigger auto-recording of all calls as well as set the storage location for records in the General section. All forwarding rules, as well as enabling the possibility to receive a second call can be set in Call settings. Device selection for speakers and microphone in the Audio section. All camera-related features for video calls can be found in the Video section.","permalink":"/docs/apps/desktop-general-app-settings--g4g5p30bgtm5ofmc1sxsa040"},{"id":"apps/ringotel/desktop-app/general/desktop-list-of-hotkeys--pwsmbmo8xheebiwps6k9rs9n","title":"List of hotkeys","description":"You can view all the available hotkeys in the Hotkeys settings tab.","permalink":"/docs/apps/desktop-list-of-hotkeys--pwsmbmo8xheebiwps6k9rs9n"},{"id":"apps/ringotel/desktop-app/general/desktop-video-settings--skf51aul86q7qafdn0bcljku","title":"Video settings","description":"1. Turn on your video camera for testing.","permalink":"/docs/apps/desktop-video-settings--skf51aul86q7qafdn0bcljku"},{"id":"apps/ringotel/desktop-app/general/desktop-voicemail--dqa3qfyebvyy59cyk38biu10","title":"Voicemail settings","description":"In case when you\u2019re unable to pick up a call, you can send it to a voicemail. It can be enabled in your desktop app or by your PBX administrator.","permalink":"/docs/apps/desktop-voicemail--dqa3qfyebvyy59cyk38biu10"}],"unlisted":false}}')}}]);